{"request": "Develop a fitness app that tracks a user's location", "response": "# Fitness App with Location Tracking

I'll help you create a comprehensive fitness app that tracks user location. Here's a complete solution with multiple approaches:

## **Option 1: React Native with Google Maps (Cross-Platform)**

### Installation
```bash
npx react-native init FitnessTracker
cd FitnessTracker
npm install @react-native-community/geolocation @react-native-community/maps
npm install react-native-maps
```

### Main App Component (`App.js`)
```javascript
import React, { useState, useEffect } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, ActivityIndicator } from 'react-native';
import MapView, { Marker, Polyline } from 'react-native-maps';
import Geolocation from '@react-native-community/geolocation';
import { Ionicons } from '@expo/vector-icons';

const FitnessTracker = () => {
  const [location, setLocation] = useState(null);
  const [route, setRoute] = useState([]);
  const [distance, setDistance] = useState(0);
  const [isTracking, setIsTracking] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const subscription = Geolocation.watchPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setLocation({ latitude, longitude });

        if (route.length > 0) {
          setRoute([...route, { latitude, longitude }]);
          calculateDistance(route, { latitude, longitude });
        }
      },
      (error) => {
        console.error('Geolocation error:', error);
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 1000,
      }
    );

    return () => subscription.remove();
  }, [route]);

  const calculateDistance = (previousPoints, currentPoint) => {
    // Simple Haversine formula implementation
    const R = 6371; // Earth's radius in km
    const dLat = (currentPoint.latitude - previousPoints[0].latitude) * Math.PI / 180;
    const dLon = (currentPoint.longitude - previousPoints[0].longitude) * Math.PI / 180;
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
              Math.cos(previousPoints[0].latitude * Math.PI / 180) *
              Math.cos(currentPoint.latitude * Math.PI / 180) *
              Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    const distance = R * c;
    setDistance(distance);
  };

  const startTracking = () => {
    setLoading(true);
    setIsTracking(true);
    setRoute([]);
    setDistance(0);

    // Get initial location
    Geolocation.getCurrentPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setLocation({ latitude, longitude });
        setRoute([{ latitude, longitude }]);
        setLoading(false);
      },
      (error) => {
        console.error('Error getting initial position:', error);
        setLoading(false);
      }
    );
  };

  const stopTracking = () => {
    setIsTracking(false);
    setLoading(false);
  };

  if (loading) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#4CAF50" />
        <Text style={styles.loadingText}>Getting your location...</Text>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <MapView
        style={styles.map}
        initialRegion={{
          latitude: location?.latitude || 37.7749,
          longitude: location?.longitude || -122.4194,
          latitudeDelta: 0.0922,
          longitudeDelta: 0.0421,
        }}
      >
        {location && <Marker coordinate={location} title="Current Location" />}
        {route.length > 1 && (
          <Polyline
            coordinates={route}
            strokeColor="#4CAF50"
            strokeWidth={4}
          />
        )}
      </MapView>

      <View style={styles.controls}>
        <View style={styles.statsContainer}>
          <Text style={styles.distanceText}>
            Distance: {distance.toFixed(2)} km
          </Text>
          <Text style={styles.timeText}>
            {isTracking ? 'Tracking...' : 'Paused'}
          </Text>
        </View>

        <View style={styles.buttonContainer}>
          {isTracking ? (
            <TouchableOpacity
              style={[styles.button, styles.stopButton]}
              onPress={stopTracking}
            >
              <Ionicons name="stop-circle" size={24} color="white" />
              <Text style={styles.buttonText}>Stop</Text>
            </TouchableOpacity>
          ) : (
            <TouchableOpacity
              style={[styles.button, styles.startButton]}
              onPress={startTracking}
            >
              <Ionicons name="play-circle" size={24} color="white" />
              <Text style={styles.buttonText}>Start</Text>
            </TouchableOpacity>
          )}
        </View>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  map: {
    flex: 1,
  },
  controls: {
    position: 'absolute',
    bottom: 20,
    left: 20,
    right: 20,
    backgroundColor: 'rgba(255, 255, 255, 0.9)',
    borderRadius: 15,
    padding: 15,
    elevation: 5,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.25,
    shadowRadius: 3.84,
  },
  statsContainer: {
    marginBottom: 15,
  },
  distanceText: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#333',
  },
  timeText: {
    fontSize: 14,
    color: '#666',
    marginTop: 5,
  },
  buttonContainer: {
    alignItems: 'center',
  },
  button: {
    flexDirection: 'row',
    alignItems: 'center"}
